export default function Home() {
    return (
        <div className="flex flex-col">
            {/* Hero Section */}
            <section className="w-full py-12 md:py-24 lg:py-32 xl:py-48 bg-black relative overflow-hidden">
                <div className="absolute inset-0 bg-gradient-to-r from-blue-900/50 to-purple-900/50 mix-blend-multiply" />
                {/* Placeholder background image gradient if no image */}
                <div className="container relative z-10 px-4 md:px-6 mx-auto">
                    <div className="flex flex-col items-center space-y-4 text-center">
                        <div className="space-y-2">
                            <h1 className="text-3xl font-bold tracking-tighter sm:text-4xl md:text-5xl lg:text-6xl/none text-white">
                                Монголын Зуслангийн Салбарын <br className="hidden sm:inline" />
                                <span className="text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-purple-400">
                                    100 Жилийн Ой
                                </span>
                            </h1>
                            <p className="mx-auto max-w-[700px] text-gray-300 md:text-xl/relaxed lg:text-base/relaxed xl:text-xl/relaxed pt-4">
                                Хүүхдийн хөгжил, хамгаалал, оролцоонд суурилсан зуслангийн хөгжлийн үндэсний тогтолцоо.
                            </p>
                        </div>
                        <div className="space-x-4">
                            <a
                                href="/camps"
                                className="inline-flex h-11 items-center justify-center rounded-md bg-white px-8 text-sm font-medium text-black transition-colors hover:bg-gray-200"
                            >
                                Зуслан хайх
                            </a>
                            <a
                                href="/about"
                                className="inline-flex h-11 items-center justify-center rounded-md border border-white px-8 text-sm font-medium text-white transition-colors hover:bg-white/10"
                            >
                                Бидний тухай
                            </a>
                        </div>
                    </div>
                </div>
            </section>

            {/* Featured Statistics / Info */}
            <section className="w-full py-12 md:py-24 bg-gray-50 dark:bg-zinc-900">
                <div className="container px-4 md:px-6 mx-auto">
                    <div className="grid gap-8 sm:grid-cols-2 lg:grid-cols-4 text-center">
                        <div className="space-y-2">
                            <h3 className="text-4xl font-bold text-primary">2006</h3>
                            <p className="text-sm text-gray-500 dark:text-gray-400 uppercase tracking-wider">Байгуулагдсан он</p>
                        </div>
                        <div className="space-y-2">
                            <h3 className="text-4xl font-bold text-primary">100+</h3>
                            <p className="text-sm text-gray-500 dark:text-gray-400 uppercase tracking-wider">Бүртгэлтэй Зуслан</p>
                        </div>
                        <div className="space-y-2">
                            <h3 className="text-4xl font-bold text-primary">2012</h3>
                            <p className="text-sm text-gray-500 dark:text-gray-400 uppercase tracking-wider">ОУЗХ-ны гишүүн</p>
                        </div>
                        <div className="space-y-2">
                            <h3 className="text-4xl font-bold text-primary">15+</h3>
                            <p className="text-sm text-gray-500 dark:text-gray-400 uppercase tracking-wider">ОУ-ын түншлэл</p>
                        </div>
                    </div>
                </div>
            </section>

            {/* Latest News / Announcements Placeholder */}
            <section className="w-full py-12 md:py-24">
                <div className="container px-4 md:px-6 mx-auto">
                    <div className="flex flex-col items-center justify-center space-y-4 text-center mb-10">
                        <h2 className="text-3xl font-bold tracking-tighter md:text-4xl">Сүүлийн үеийн мэдээ</h2>
                        <p className="max-w-[900px] text-gray-500 md:text-xl/relaxed lg:text-base/relaxed xl:text-xl/relaxed">
                            Монголын Үндэсний Зуслангуудын Холбооны цаг үеийн мэдээлэл, үйл ажиллагаа.
                        </p>
                    </div>

                    <div className="grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
                        {[1, 2, 3].map((i) => (
                            <div key={i} className="group relative overflow-hidden rounded-lg shadow-md transition-all hover:shadow-lg border">
                                <div className="aspect-video w-full bg-gray-200" />
                                <div className="p-4 bg-white">
                                    <h3 className="font-semibold text-lg line-clamp-2 mb-2 group-hover:text-primary transition-colors">
                                        Олон улсын зуслангийн эрдэмтэн судлаачдын 3 дахь хурал болно
                                    </h3>
                                    <p className="text-sm text-gray-500 line-clamp-3">
                                        Ази номхон далайн орнуудын болон бусад олон улсын судлаачид оролцох уг хурлын бүртгэл эхэллээ...
                                    </p>
                                    <div className="mt-4 text-sm font-medium text-primary">Цааш унших →</div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </section>
        </div>
    )
}
